-- migrations/001_initial.sql
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kyros_user_id text UNIQUE NOT NULL, name text NOT NULL, avatar text, bio text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'available', preferences jsonb NOT NULL DEFAULT '{}', disabled boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), last_login_at timestamptz);
CREATE TABLE user_sessions (id text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), tokens text NOT NULL, access_expires_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, user_agent text, created_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE auth_attempts (id text PRIMARY KEY, verifier text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, description text NOT NULL DEFAULT '', settings jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), name text NOT NULL, permissions text[] NOT NULL DEFAULT '{}', is_owner boolean NOT NULL DEFAULT false, UNIQUE(workspace_id,name), UNIQUE(id,workspace_id));
CREATE TABLE workspace_members (workspace_id uuid NOT NULL REFERENCES workspaces(id), user_id uuid NOT NULL REFERENCES users(id), role_id uuid NOT NULL, state text NOT NULL DEFAULT 'active' CHECK(state IN ('active','disabled','banned')), joined_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(workspace_id,user_id), FOREIGN KEY(role_id,workspace_id) REFERENCES roles(id,workspace_id));
CREATE TABLE categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), name text NOT NULL, position integer NOT NULL DEFAULT 0, UNIQUE(id,workspace_id));
CREATE TABLE projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), name text NOT NULL, description text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,workspace_id));
CREATE TABLE channels (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), category_id uuid, project_id uuid, name text NOT NULL, description text NOT NULL DEFAULT '', type text NOT NULL DEFAULT 'text' CHECK(type IN ('text','announcement','project','monitoring')), position integer NOT NULL DEFAULT 0, archived boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,workspace_id), FOREIGN KEY(category_id,workspace_id) REFERENCES categories(id,workspace_id), FOREIGN KEY(project_id,workspace_id) REFERENCES projects(id,workspace_id));
CREATE TABLE technical_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), kind text NOT NULL CHECK(kind IN ('bot','service')), name text NOT NULL, description text NOT NULL DEFAULT '', token_hash text UNIQUE, permissions text[] NOT NULL DEFAULT '{}', revoked boolean NOT NULL DEFAULT false, last_used_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,workspace_id));
CREATE TABLE messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, channel_id uuid NOT NULL, user_id uuid REFERENCES users(id), technical_id uuid, content text NOT NULL CHECK(length(content) BETWEEN 1 AND 8000), reply_to uuid REFERENCES messages(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), edited_at timestamptz, deleted_at timestamptz, FOREIGN KEY(channel_id,workspace_id) REFERENCES channels(id,workspace_id), FOREIGN KEY(technical_id,workspace_id) REFERENCES technical_accounts(id,workspace_id), CHECK ((user_id IS NULL) <> (technical_id IS NULL)));
CREATE INDEX messages_cursor ON messages(channel_id,created_at DESC,id DESC);
CREATE TABLE message_reactions (message_id uuid NOT NULL REFERENCES messages(id) ON DELETE CASCADE, actor_id text NOT NULL, emoji text NOT NULL, PRIMARY KEY(message_id,actor_id,emoji));
CREATE TABLE channel_members (channel_id uuid NOT NULL REFERENCES channels(id), user_id uuid NOT NULL REFERENCES users(id), muted boolean NOT NULL DEFAULT false, following boolean NOT NULL DEFAULT true, PRIMARY KEY(channel_id,user_id));
CREATE TABLE boards (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), project_id uuid, name text NOT NULL, UNIQUE(id,workspace_id), FOREIGN KEY(project_id,workspace_id) REFERENCES projects(id,workspace_id));
CREATE TABLE board_columns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, board_id uuid NOT NULL, name text NOT NULL, position integer NOT NULL DEFAULT 0, UNIQUE(id,workspace_id), FOREIGN KEY(board_id,workspace_id) REFERENCES boards(id,workspace_id));
CREATE TABLE tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), column_id uuid NOT NULL, title text NOT NULL, description text NOT NULL DEFAULT '', priority text NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high','urgent')), tags text[] NOT NULL DEFAULT '{}', assignee uuid REFERENCES users(id), due_at timestamptz, checklist jsonb NOT NULL DEFAULT '[]', links jsonb NOT NULL DEFAULT '[]', position double precision NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(column_id,workspace_id) REFERENCES board_columns(id,workspace_id));
CREATE TABLE task_comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id uuid NOT NULL REFERENCES tasks(id), user_id uuid NOT NULL REFERENCES users(id), content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE pages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), project_id uuid, title text NOT NULL, blocks jsonb NOT NULL DEFAULT '[]', revision integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(project_id,workspace_id) REFERENCES projects(id,workspace_id));
CREATE TABLE webhooks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), channel_id uuid NOT NULL, technical_id uuid NOT NULL, name text NOT NULL, token_hash text UNIQUE NOT NULL, revoked boolean NOT NULL DEFAULT false, allow_tasks boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(channel_id,workspace_id) REFERENCES channels(id,workspace_id), FOREIGN KEY(technical_id,workspace_id) REFERENCES technical_accounts(id,workspace_id));
CREATE TABLE events (seq bigserial PRIMARY KEY, id uuid UNIQUE NOT NULL DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), type text NOT NULL, source text NOT NULL, actor text, payload jsonb NOT NULL DEFAULT '{}', metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX events_workspace_seq ON events(workspace_id,seq);
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), user_id uuid NOT NULL REFERENCES users(id), type text NOT NULL, title text NOT NULL, body text NOT NULL DEFAULT '', priority text NOT NULL DEFAULT 'normal', state text NOT NULL DEFAULT 'unread' CHECK(state IN ('unread','read','dismissed')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE integrations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), provider text NOT NULL, name text NOT NULL, config jsonb NOT NULL DEFAULT '{}', secret text, state text NOT NULL DEFAULT 'unconfigured');
CREATE TABLE feature_flags (workspace_id uuid NOT NULL REFERENCES workspaces(id), key text NOT NULL, enabled boolean NOT NULL DEFAULT false, PRIMARY KEY(workspace_id,key));
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), actor text NOT NULL, action text NOT NULL, target text, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE attachments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), user_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, mime text NOT NULL, size integer NOT NULL, storage_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE custom_emojis (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), name text NOT NULL, attachment_id uuid NOT NULL REFERENCES attachments(id), UNIQUE(workspace_id,name));
CREATE TABLE monitoring_targets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), name text NOT NULL, kind text NOT NULL CHECK(kind IN ('http','heartbeat')), url text, state text NOT NULL DEFAULT 'unknown', last_heartbeat timestamptz, last_checked_at timestamptz, latency_ms integer, UNIQUE(workspace_id,name));
CREATE TABLE monitoring_checks (id bigserial PRIMARY KEY, target_id uuid NOT NULL REFERENCES monitoring_targets(id), state text NOT NULL, latency_ms integer, detail text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX monitoring_checks_recent ON monitoring_checks(target_id,created_at DESC);
CREATE TABLE webhook_deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), url text NOT NULL, secret text NOT NULL, payload jsonb NOT NULL, state text NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), last_error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbound_webhooks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), name text NOT NULL, url text NOT NULL, secret text NOT NULL, enabled boolean NOT NULL DEFAULT true);
CREATE TABLE idempotency_keys (key text NOT NULL, webhook_id uuid NOT NULL REFERENCES webhooks(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(webhook_id,key));
